facilityFormItem.valueChangedEventHandler:
window.checkDate(formItem.name, null, ESS.L('@HRPROVACATIONS.ERROR_DATE_BEGIN'));
window.checkDate('EndDateRecall', formItem.name, ESS.L('@HRPROVACATIONS.ERROR_DATE_END'));
window.checkDurationRecall(formItem);
window.setDurationRecall();

        if (formItem.value > 0) {
          var initiatorId = functions.getValues().InitiatorId;
          var beginDate = functions.getValues().BeginDateRecall;
          var endDate = functions.getValues().EndDateRecall;
          var currentVacationData = functions.getValues().CurrentVacationData;
          var url = `/api/functions/CheckVacationHasHolidayRecall?periodBegin=${beginDate}&periodEnd=${endDate}&employeeId=${initiatorId}&currentVacationData=${currentVacationData}`;
          ESS.network.sendRequest(url).then(function (warning){
            if(warning.length > 0)
              ESS.toasts.showToast(warning, 'warning', true);
          });

          window.checkDurationShift();
          window.setDayCountCompensation();
          window.setDurationShift();
        }

window.checkDate(formItem.name, null, ESS.L('@HRPROVACATIONS.ERROR_DATE_BEGIN'));
window.checkDate('EndDateShift', formItem.name, ESS.L('@HRPROVACATIONS.ERROR_DATE_END'));
window.setDurationShift();

        if (formItem.value > 0) {
          var initiatorId = functions.getValues().InitiatorId;
          var beginRecall = functions.getValues().BeginDateRecall;
          var endRecall = functions.getValues().EndDateRecall;
          var beginShift = functions.getValues().BeginDateShift;
          var endShift = functions.getValues().EndDateShift;
          var currentVacationData = functions.getValues().CurrentVacationData;
          var url = `/api/functions/CheckVacationHasHolidayShift?beginRecall=${beginRecall}&endRecall=${endRecall}&beginShift=${beginShift}&endShift=${endShift}&employeeId=${initiatorId}&currentVacationData=${currentVacationData}`;
          ESS.network.sendRequest(url).then(function (warning){
            if(warning.length > 0)
              ESS.toasts.showToast(warning, 'warning', true);
          });

          window.checkDurationShift();
          window.setDayCountCompensation();
        }

var isCompensation = formItem.value == "1";
functions.setIsItemHidden('DayCountCompensation', !isCompensation);
if (isCompensation) {
  window.setDayCountCompensation();
}
else {
  functions.setValue('DayCountCompensation', 0);
}
window.checkDurationShift();

facility.openingEventHandler:
    ESS.network.sendRequest(`/api/functions/GetInitiatorId`)
    .then(function (initiatorId){
      ESS.network.sendRequest(`/api/functions/GetEmployeeCertificates`)																																			
      .then(function (certs) {
        if (certs.length == 0) {
          ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.ERROR_COMMON'), ESS.L('@HRPROVACATIONS.FACILITIES_SENDSTATEMENT_NO_CERTIFICATES_ERROR'));
          reject();
        } 
        else {
          ESS.network.sendRequest(`/api/functions/GetPostListByPerson`)
          .then(function (employee){
            ESS.network.sendRequest(`/api/functions/CheckEmployeeConsentSigned`)
            .then(function (isConsentSigned) {
              if (isConsentSigned != true && employee.positions.length == 1) {
                ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.ERROR_COMMON'), ESS.L('@HRPROVACATIONS.FACILITIES_SHIFTVACATION_CONSENT_ERROR'));
                reject();
              }
              else {
                ESS.network.sendRequest(`/api/functions/GetVacationRecallStatementTemplateId?employeeId=${initiatorId}&isShiftVacation=false&isVacationRecall=true&isAuthorManager=false`)																																																		
                .then(function (VacationStatementData) {
                  if (VacationStatementData.Error.length == 0) {
                    if (employee.positions.length == 1) {
                      functions.setIsItemHidden('PerformerInfo', true);
                    }

                    var templateId = JSON.parse(VacationStatementData.TemplateId);
                    var docKindId = JSON.parse(VacationStatementData.DocumentKindId);
                    functions.setValue('TemplateId', templateId);
                    functions.setValue('DocumentKindId', docKindId);

                    functions.setIsItemHidden('DayCountCompensation', true);
                    
                    var assignmentId = functions.getValues().AssignmentId;
                    ESS.network.sendRequest(`/api/functions/GetVacationDataForReworkRecall?assignmentId=${assignmentId}`)
                    .then(function (vacationData){
                      if (vacationData) {
                        functions.setValue('InitiatorId', vacationData.InitiatorId);
                        functions.setValue('CurrentVacationData', JSON.stringify(vacationData.CurrentVacations));
                        functions.setValue('CurrentVacation', vacationData.VacationPeriod);
                        functions.setValue('VacationTypeCurrent', vacationData.VacationTypeId);
                        functions.setValue('StatementId', vacationData.StatementId);
                        functions.setValue('PerformerInfo', vacationData.PerformerInfo);
                        functions.setValue('Reason', vacationData.Reason);
                        functions.setValue('Field_Причина', vacationData.Reason);
                        functions.setValue('CompensationKind', vacationData.CompensationKind);
                        functions.setIsItemHidden('DayCountCompensation', vacationData.CompensationKind != "1");
              
                        functions.setValue('BeginDateCurrent', vacationData.BeginDateCurrent);
                        functions.setValue('EndDateCurrent', vacationData.EndDateCurrent);
                        functions.setValue('DurationCurrent', vacationData.DurationCurrent);
                        
                        functions.setValue('BeginDateRecall', vacationData.BeginDateRecall);
                        functions.setValue('EndDateRecall', vacationData.EndDateRecall);
                        functions.setValue('DurationRecall', vacationData.DurationRecall);
                        
                        functions.setValue('BeginDateShift', vacationData.BeginDateShift);
                        functions.setValue('EndDateShift', vacationData.EndDateShift);
                        functions.setValue('DurationShift', vacationData.DurationShift);
                      }
                      resolve();
                    })
                    .catch(function (error) {
                      ESS.toasts.showToast(error.message, 'danger', false);
                    });
                  } 
                  else {
                    ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.ERROR_COMMON'), VacationStatementData.Error);
                  }
                })
                .catch(function (error) {
                  ESS.toasts.showToast(error.message, 'danger', false);
                });
              }
            });
          });
        }
      })
      .catch(function (error) {
        ESS.toasts.showToast(error.message, 'danger', false);
      });
    })
    .catch(function (error) {
      ESS.toasts.showToast(error.message, 'danger', false);
    });

facility.openedEventHandler:
    window.setDurationRecall = function () {
      var initiatorId = functions.getValues().InitiatorId;
      var beginDate = functions.getValues().BeginDateRecall;
      var endDate = functions.getValues().EndDateRecall;
      var currentVacationData = functions.getValues().CurrentVacationData;
      if (beginDate != null && endDate != null) {
        var url = `/api/functions/RecallDurationInCalendarDaysWithoutHoliday?startDate=${beginDate}&endDate=${endDate}&employeeId=${initiatorId}&currentVacationData=${currentVacationData}`
        ESS.network.sendRequest(url)
        .then(function (newDurationValue) {
          functions.setValue('DurationRecall', newDurationValue);
        });
      }
    }

    window.setDurationShift = function (rowIndex) {
      var initiatorId = functions.getValues().InitiatorId;
      var beginDateRecall = functions.getValues().BeginDateRecall;
      var endDateRecall = functions.getValues().EndDateRecall;
      var beginDateShift = functions.getValues().BeginDateShift;
      var endDateShift = functions.getValues().EndDateShift;
      var currentVacationData = functions.getValues().CurrentVacationData;
      if (beginDateRecall != null && endDateRecall != null && beginDateShift != null && endDateShift != null) {
        var url = `/api/functions/ShiftDurationInCalendarDaysWithoutHoliday?beginDateRecall=${beginDateRecall}&endDateRecall=${endDateRecall}&beginDateShift=${beginDateShift}&endDateShift=${endDateShift}&employeeId=${initiatorId}&currentVacationData=${currentVacationData}`
        ESS.network.sendRequest(url)
        .then(function (newDurationValue) {
          functions.setValue('DurationShift', newDurationValue);
        });
      }
    }
    window.setDurationShift();

    window.setDayCountCompensation = function () {
      var isCompensation = functions.getValues().CompensationKind == "1";
      if (isCompensation) {
        var initiatorId = functions.getValues().InitiatorId;
        var beginDateRecall = functions.getValues().BeginDateRecall;
        var endDateRecall = functions.getValues().EndDateRecall;
        var durationRecall = functions.getValues().DurationRecall;
        var durationShift = functions.getValues().DurationShift;
        var currentVacationData = functions.getValues().CurrentVacationData;
        var url = `/api/functions/GetDayCountCompensation?beginRecall=${beginDateRecall}&endRecall=${endDateRecall}&durationRecall=${durationRecall}&durationShift=${durationShift}&employeeId=${initiatorId}&currentVacationData=${currentVacationData}`
        ESS.network.sendRequest(url)
        .then(function (dayCountCompensation) {
          functions.setValue('DayCountCompensation', dayCountCompensation);
        });
      }
    }
    
    window.checkDurationShift = function () {
      var durationRecall = +functions.getValues().DurationRecall;
      var durationShift = +functions.getValues().DurationShift;
      functions.removeError(window.errorDurationShift);
      if (durationShift > 0 && durationRecall > 0) {
        if (durationShift > durationRecall) {
          window.errorDurationShift = functions.showError(ESS.L('@HRPROVACATIONS.FACILITIES_NNSELFRECALLVACATIONEMPLOYEE_LIMITDAYSSHIFT_ERROR'));
        }
      }
    }

    window.checkDurationRecall = function (formItem) {
      var endDateRecall = new Date(formItem.value).setHours(0, 0, 0, 0);
      var beginDateCurrent = new Date(functions.getValues().BeginDateCurrent).setHours(0, 0, 0, 0);
      var endDateCurrent = new Date(functions.getValues().EndDateCurrent).setHours(0, 0, 0, 0);
      functions.removeError(window[`error${formItem.name}`]);
      if (endDateRecall < beginDateCurrent || endDateRecall > endDateCurrent) {
       window[`error${formItem.name}`] = functions.showError(ESS.L('@HRPROVACATIONS.FACILITIES_NNSELFRECALLVACATIONEMPLOYEE_DATERECALL_ERROR'), undefined, ESS.enums.FormErrorType.UNSPECIFIED, formItem.name);
      }
    }

    window.getDate = function (formItemName) {
      var date = functions.getValues()[`${formItemName}`];
      return date == null ? null : new Date(new Date(date).setHours(0, 0, 0, 0));
    }

    window.checkDate = function (formItemName, formItemNameBegin, errorText) {
      var formItemValue = functions.getValues()[`${formItemName}`];
      if (formItemValue != null) {
        var today = new Date().setHours(0, 0, 0, 0);
        var date = window.getDate(formItemName);
        var beginDate = window.getDate(formItemNameBegin);
        functions.removeError(window[`errorDate${formItemName}`]);
        if ((date.getTime() < today) || (beginDate != null && date.getTime() < beginDate.getTime())) {
          window[`errorDate${formItemName}`] = functions.showError(errorText, undefined, ESS.enums.FormErrorType.UNSPECIFIED, formItemName);
        }
      }
    }

facility.beforeSubmitEventHandler:
    var initiatorId = functions.getValues().InitiatorId;
    var vacationTypeId = functions.getValues().VacationTypeCurrent;
    var statementId = functions.getValues().StatementId;
    var dayCountCompensation = functions.getValues().DayCountCompensation;
    var currentVacationData = functions.getValues().CurrentVacationData;
    functions.setValue('Field_Дней компенсации', dayCountCompensation);

    var durationRecall = functions.getValues().DurationRecall;
    functions.setValue('Field_Дней отзыва', durationRecall);
    var beginDateRecall = functions.getValues().BeginDateRecall;
    var endDateRecall = functions.getValues().EndDateRecall;
    var datesRecall = [];
    datesRecall.push(beginDateRecall);
    datesRecall.push(endDateRecall);
    var getFormatDatesRecall = ESS.network.sendRequest(`/api/functions/GetFormatDates?employeeId=${initiatorId}&dates=%5B${datesRecall}%5D`)
    .then(function (dates) {
      functions.setValue('Field_Дата начала части отпуска', dates[0]);
      functions.setValue('Field_Дата окончания части отпуска', dates[1]);
    });
    
    var durationShift = functions.getValues().DurationShift;
    functions.setValue('Field_Дней переноса', durationShift);
    var beginDateShift = functions.getValues().BeginDateShift;
    var endDateShift = functions.getValues().EndDateShift;
    var datesShift = [];
    datesShift.push(beginDateShift);
    datesShift.push(endDateShift);
    var getFormatDatesShift = ESS.network.sendRequest(`/api/functions/GetFormatDates?employeeId=${initiatorId}&dates=%5B${datesShift}%5D`)
    .then(function (dates) {
      functions.setValue('Field_Дата_начала_отпуска', dates[0]);
      functions.setValue('Field_Дата_окончания_отпуска', dates[1]);
    });

    var validateVacationData = ESS.scripts.HRProVacations.validateRecallVacationData({ functions, initiatorId, statementId, vacationTypeId, beginDateRecall, endDateRecall, durationRecall, beginDateShift, endDateShift, durationShift, dayCountCompensation, currentVacationData });
    
    Promise.all([
      getFormatDatesRecall,
      getFormatDatesShift,
      validateVacationData
    ])
    .then((success) => { resolve() }, (error) => { reject() });
